
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_bhandhlyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_bhandhlyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.222664645535906e+00, -2.181630627985780e+00, -2.124162762008664e+00, -2.044618590855565e+00, -1.936358015253053e+00, -1.792527238722494e+00, -1.607885614285739e+00, -1.381986604086114e+00, -1.122958739997159e+00, -8.473780066418334e-01, -5.699196367783084e-01, -3.865083749147149e-01, -3.348232998547311e-01, -2.798930514777793e-01, -2.029738351081767e-01, -1.245894625382009e-01, -7.153529587044499e-02, -4.870018472646388e-02, -3.057895618784941e-02, -2.086182206226636e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


